create table if not exists public.taxonomy_attribute_templates(id uuid primary key default gen_random_uuid(),slug text not null unique,input_kind text not null,value_kind text not null,labels jsonb not null default '{}'::jsonb,descriptions jsonb not null default '{}'::jsonb,options jsonb not null default '[]'::jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table if not exists public.taxonomy_nodes(id uuid primary key default gen_random_uuid(),slug text not null unique,parent_slug text null,node_type text not null,asset_class_slug text not null,market_bucket text not null,sort_order integer not null default 0,is_active boolean not null default true,supports_current_protocol boolean not null default false,labels jsonb not null default '{}'::jsonb,aliases jsonb not null default '{}'::jsonb,attribute_template_refs text[] not null default '{}'::text[],metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint taxonomy_nodes_node_type_chk check (node_type in ('asset_class','category','subcategory')));

create index if not exists idx_taxonomy_nodes_parent_slug on public.taxonomy_nodes(parent_slug);

create index if not exists idx_taxonomy_nodes_asset_class_slug on public.taxonomy_nodes(asset_class_slug);

create index if not exists idx_taxonomy_nodes_market_bucket on public.taxonomy_nodes(market_bucket);

create index if not exists idx_taxonomy_nodes_node_type on public.taxonomy_nodes(node_type);

create index if not exists idx_taxonomy_nodes_labels_gin on public.taxonomy_nodes using gin(labels);

create index if not exists idx_taxonomy_nodes_aliases_gin on public.taxonomy_nodes using gin(aliases);

drop trigger if exists update_taxonomy_attribute_templates_updated_at on public.taxonomy_attribute_templates;

create trigger update_taxonomy_attribute_templates_updated_at before update on public.taxonomy_attribute_templates for each row execute function update_updated_at_column();

drop trigger if exists update_taxonomy_nodes_updated_at on public.taxonomy_nodes;

create trigger update_taxonomy_nodes_updated_at before update on public.taxonomy_nodes for each row execute function update_updated_at_column();

alter table public.taxonomy_attribute_templates enable row level security;

alter table public.taxonomy_nodes enable row level security;

drop policy if exists taxonomy_attribute_templates_read_all on public.taxonomy_attribute_templates;

create policy taxonomy_attribute_templates_read_all on public.taxonomy_attribute_templates for select using (true);

drop policy if exists taxonomy_nodes_read_all on public.taxonomy_nodes;

create policy taxonomy_nodes_read_all on public.taxonomy_nodes for select using (true);

